using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
internal sealed partial class ModernWorkspace {
 void ProjectHub(StackPanel root,ProjectSpace project){
  var tasks=store.Value.tasks.Where(t=>t.project==project.name).ToList();var entries=store.Value.budget.entries.Where(e=>e.project==project.name).ToList();long spent=entries.Where(e=>e.kind=="expense").Sum(e=>e.cents),income=entries.Where(e=>e.kind=="income").Sum(e=>e.cents);
  var row=new UniformGrid{Columns=3,Margin=new Thickness(0,10,0,20)};foreach(var value in new[]{new[]{tasks.Count(t=>t.status!="done")+"","tâches restantes"},new[]{Finance.Money(spent),"dépenses liées"},new[]{project.budgetCents>0?Finance.Money(project.budgetCents-spent):"À définir","budget restant"}}){var panel=new StackPanel();panel.Children.Add(T(value[0],22));panel.Children.Add(T(value[1],11,Muted,new Thickness(0,7,0,0)));var card=Box(panel,new Thickness(15));card.Margin=new Thickness(0,0,12,0);row.Children.Add(card);}root.Children.Add(row);
  var body=new StackPanel();var actions=new WrapPanel();var mode=store.Value.modes.FirstOrDefault(m=>m.id==project.launchModeId);if(mode!=null)actions.Children.Add(Btn("Lancer "+mode.name,delegate{RunMode(mode,true);},true));actions.Children.Add(Btn("Configurer le projet",delegate{ConfigureProjectHub(project);},false,true));actions.Children.Add(Btn("+ Dépense liée",delegate{EditBudgetEntry(null,"expense");},false,true));actions.Children.Add(Btn("Ouvrir mes notes à droite",delegate{var note=store.Value.pages.FirstOrDefault(n=>!n.trashed&&n.project==project.name);store.Value.settings.Desk.enabled=true;store.Value.settings.Desk.panel="Notes";store.Value.settings.Desk.noteId=note==null?"":note.id;owner.Save();Refresh();},false,true));body.Children.Add(actions);
  if(project.budgetCents>0)body.Children.Add(new ProgressBar{Maximum=100,Value=Math.Min(100,100.0*spent/project.budgetCents),Foreground=Accent,Background=FaintLine,Height=4,Margin=new Thickness(0,15,0,5)});
  foreach(var entry in entries.OrderByDescending(e=>e.date).Take(5)){var item=entry;body.Children.Add(Btn(item.title+" · "+(item.kind=="income"?"+":"−")+Finance.Money(item.cents),delegate{EditBudgetEntry(item,item.kind);},false,true));}if(income>0)body.Children.Add(T("Revenus liés : "+Finance.Money(income),11,Muted,new Thickness(0,10,0,0)));
  var panelCard=Card("Pilotage du projet",body);panelCard.Margin=new Thickness(0,0,0,20);root.Children.Add(panelCard);
 }
 void ConfigureProjectHub(ProjectSpace source){
  StackPanel body,actions;var w=Dialog("Configurer "+source.name,out body,out actions,600);var amount=new TextBox{Text=(source.budgetCents/100m).ToString("0.00",System.Globalization.CultureInfo.GetCultureInfo("fr-FR")),MaxLength=20};Field(body,"Budget total du projet (€), 0 si aucun",amount);var modes=store.Value.modes.ToList();var labels=new[]{"Aucun mode"}.Concat(modes.Select(m=>m.name)).ToArray();int current=modes.FindIndex(m=>m.id==source.launchModeId);var mode=Combo(labels,labels[current+1]);Field(body,"Mode à lancer avec ce projet",mode);body.Children.Add(T("Les dépenses liées au projet sont les mêmes opérations que dans Mon budget.",12,Muted));var error=T("",12,AccentText);body.Children.Add(error);actions.Children.Add(Btn("Annuler",delegate{w.DialogResult=false;},false,true));actions.Children.Add(Btn("Enregistrer",delegate{long value;if(!Finance.ParseMoney(amount.Text,true,out value)||value<0){error.Text="Indiquez un montant positif ou nul.";return;}long before=source.budgetCents;string old=source.launchModeId;source.budgetCents=value;source.launchModeId=mode.SelectedIndex==0?"":modes[mode.SelectedIndex-1].id;if(!owner.Save()){source.budgetCents=before;source.launchModeId=old;return;}w.DialogResult=true;},true));ShowWindow(w);Refresh();
 }
}
